  const near=entry.contexts.filter(id=>{const c=window.READING_HELP_DATA.contexts[id].source;return source.selection&&c.start<=source.selection[0]&&source.selection[0]<=c.end;}).sort((a,b)=>{const x=window.READING_HELP_DATA.contexts[a].source,y=window.READING_HELP_DATA.contexts[b].source;return (x.end-x.start)-(y.end-y.start);})[0];
